import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { BlankVial } from "@/components/BlankVial";
import { MicrositeContact } from "@/components/MicrositeContact";
import { StorefrontRuntime } from "@/components/StorefrontRuntime";
import { PARTNER_CATALOG } from "@/lib/partner-catalog";

export const metadata: Metadata = { title: "Partner Microsite Preview", robots: { index: false, follow: false } };

type TemplateKey = "creator" | "studio" | "catalogue" | "framework" | "volume" | "institutional";
type StoreVariant = "default" | "editorial" | "precision" | "direct";

type Product = { sku: string; name: string; price: string; stock: string; category: string; coa: string | null; batch: string; purity: string };

const PRODUCTS: Product[] = PARTNER_CATALOG.map((product) => ({
  sku: product.sku,
  name: product.name,
  price: `$${product.retailPrice.toFixed(2)}`,
  stock: `${product.stock} available`,
  category: product.category,
  coa: product.coa,
  batch: product.batch,
  purity: product.purity,
}));

const TEMPLATE_NAMES: Record<TemplateKey, string> = { creator: "Editorial", studio: "Precision", catalogue: "Direct", framework: "Framework", volume: "Volume", institutional: "Institutional" };

export default async function TemplateConceptPage({ params }: { params: Promise<{ template: string }> }) {
  const { template: rawTemplate } = await params;
  if (!(rawTemplate in TEMPLATE_NAMES)) notFound();
  const template = rawTemplate as TemplateKey;
  if (template === "creator") return <><StorefrontRuntime /><SignatureStore /></>;
  if (template === "studio") return <><StorefrontRuntime /><LedgerStore /></>;
  if (template === "catalogue") return <><StorefrontRuntime /><MarketStore /></>;
  return <><StorefrontRuntime /><ScaleStore template={template} /></>;
}

function PreviewBar({ template }: { template: TemplateKey }) {
  return <div className="relative z-50 border-b border-black/10 bg-white px-4 py-2.5 text-center text-[9px] font-bold uppercase tracking-[.15em] text-[#5d6068]">Live microsite concept · {TEMPLATE_NAMES[template]} · <Link href="/#templates" className="underline underline-offset-4">Return to EVLV Partners</Link></div>;
}

